#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tic_rate_is_30() {
        let mut s = DukeSession::new();
        assert_eq!(s.tic_rate(), 30);
        s.tick(DukeInput::default());
        assert_eq!(s.tic, 1);
    }
}
